funcao dividir(a: inteiro, b: inteiro) -> Resultado<inteiro, cadeia> {
    se (b == 0) {
        retorne Resultado::Erro("erro");
    }
    retorne Resultado::Ok(0);
}

funcao inicio() {
    seja mutavel a: inteiro = leia();
    seja mutavel b: inteiro = leia();
    escolha dividir(a, b) {
        caso Resultado::Ok(q) => { escreva(q); }
        caso Resultado::Erro(e) => { escreva(e); }
    }
}
